import{_ as a,o as l,c as t,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Code Walkthrough: RGW Bucket Notifications with AMQA/Kafka","description":"","frontmatter":{"title":"Ceph Code Walkthrough: RGW Bucket Notifications with AMQA/Kafka","date":"2021-04-28T00:00:00.000Z","updated":"2021-04-28T00:00:00.000Z","tags":["Ceph","RGW","Bucket Notifications","AMQP","Kafka"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Code_Walkthrough_-_RGW_Bucket_Notifications_with_AMQA_Kafka.md","filePath":"posts/2021/Ceph_Code_Walkthrough_-_RGW_Bucket_Notifications_with_AMQA_Kafka.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Ceph_Code_Walkthrough_-_RGW_Bucket_Notifications_with_AMQA_Kafka.md"};function r(s,i,u,h,_,n){return l(),t("div",null,[...i[0]||(i[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议由Mike Perez主持，Yuval主讲，主题为Ceph的Reno版本中Gateway的Bucket Notifications功能，特别关注了与AMQP和Kafka的集成实现。会议通过代码走查的方式，深入探讨了配置和发送通知的细节。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Bucket Notifications概述</strong></p><ul><li>功能简介：当对象在存储中创建或删除时，系统会向预配置的端点发送通知。</li><li>两种模式： <ul><li><strong>Push模式</strong>：事件发生时立即发送通知。</li><li><strong>Pull模式</strong>：所有通知存储在特殊的pub/sub区域中，计划未来弃用。</li></ul></li></ul></li><li><p><strong>配置流程</strong></p><ul><li>主要涉及的文件：<code>rgw_rest_pubsub</code>和<code>rgw_rest_pubsub_common</code>。</li><li>配置API：包括创建、删除、列出主题和通知等。</li><li>系统对象存储：所有配置信息以系统对象的形式存储。</li></ul></li><li><p><strong>数据结构</strong></p><ul><li>定义在<code>rgw_pubsub.h</code>中，包括主题、通知、过滤器等。</li><li>过滤器类型：前缀、后缀、正则表达式、标签和元数据。</li></ul></li><li><p><strong>通知发送流程</strong></p><ul><li>从<code>rgw_ops</code>开始，涉及<code>publish_reserve</code>和<code>publish_commit</code>函数。</li><li>同步和异步通知处理： <ul><li>同步：直接发送通知。</li><li>异步（持久化）：先存储通知，后续再发送。</li></ul></li></ul></li><li><p><strong>端点实现</strong></p><ul><li>涉及Kafka和AMQP的实现细节。</li><li>端点管理：初始化、关闭、发送确认等。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了Bucket Notifications的基本功能和配置流程。</li><li>明确了同步和异步通知的处理方式。</li><li>确认了端点（如Kafka和AMQP）的实现细节。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续优化和完善Bucket Notifications的功能。</li><li>考虑未来可能的新端点类型集成。</li><li>如果有进一步的问题或需要详细解释，可以通过邮件联系Yuval。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议中提到的某些API和模式（如非AWS合规API和Pull模式）计划弃用，不建议在新开发中使用。</li><li>推荐使用AWS CLI或o3border3工具进行配置，手动编写REST消息较为复杂且不推荐。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>感谢Yuval的详细讲解和所有参与者的积极参与。希望大家有一个愉快的剩余时间。</p><p>以上是本次会议的详细纪要，涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</p>',14)])])}const p=a(o,[["render",r]]);export{d as __pageData,p as default};
